echo '"""
Simple Cipher Toolkit

This module provides implementations for four classical ciphers: Caesar, Vigenere, Rail-Fence, and Substitution.
Each cipher includes methods for encryption, decryption, and frequency analysis.

"""
import string
from collections import Counter

ALPHABET = string.ascii_uppercase

class CaesarCipher:
    """Caesar cipher implementation."""

    def __init__(self, shift=3):
        """Initialize with a shift key."""
        self.shift = shift % 26

    def encrypt(self, plaintext):
        """Encrypt plaintext using Caesar cipher."""
        result = []
        for ch in plaintext.upper():
            if ch in ALPHABET:
                idx = (ALPHABET.index(ch) + self.shift) % 26
                result.append(ALPHABET[idx])
            else:
                result.append(ch)
        return ''.join(result)

    def decrypt(self, ciphertext):
        """Decrypt ciphertext using Caesar cipher."""
        result = []
        for ch in ciphertext.upper():
            if ch in ALPHABET:
                idx = (ALPHABET.index(ch) - self.shift) % 26
                result.append(ALPHABET[idx])
            else:
                result.append(ch)
        return ''.join(result)

    def frequency_analysis(self, text):
        """Frequency analysis of letters in the text."""
        text = text.upper()
        freq = Counter(ch for ch in text if ch in ALPHABET)
        total = sum(freq.values())
        return {ch: freq[ch]/total for ch in ALPHABET}


class VigenereCipher:
    """Vigenere cipher implementation."""

    def __init__(self, key='KEY'):
        """Initialize with a key string."""
        self.key = key.upper()

    def encrypt(self, plaintext):
        """Encrypt plaintext using Vigenere cipher."""
        result = []
        key_len = len(self.key)
        key_indices = [ALPHABET.index(k) for k in self.key]
        for i, ch in enumerate(plaintext.upper()):
            if ch in ALPHABET:
                idx = (ALPHABET.index(ch) + key_indices[i % key_len]) % 26
                result.append(ALPHABET[idx])
            else:
                result.append(ch)
        return ''.join(result)

    def decrypt(self, ciphertext):
        """Decrypt ciphertext using Vigenere cipher."""
        result = []
        key_len = len(self.key)
        key_indices = [ALPHABET.index(k) for k in self.key]
        for i, ch in enumerate(ciphertext.upper()):
            if ch in ALPHABET:
                idx = (ALPHABET.index(ch) - key_indices[i % key_len]) % 26
                result.append(ALPHABET[idx])
            else:
                result.append(ch)
        return ''.join(result)

    def frequency_analysis(self, text):
        """Frequency analysis of letters in the text."""
        text = text.upper()
        freq = Counter(ch for ch in text if ch in ALPHABET)
        total = sum(freq.values())
        return {ch: freq[ch]/total for ch in ALPHABET}


class RailFenceCipher:
    """Rail Fence cipher implementation."""

    def __init__(self, rails=3):
        """Initialize with number of rails."""
        self.rails = rails

    def encrypt(self, plaintext):
        """Encrypt plaintext using Rail Fence cipher."""
        rails = [''] * self.rails
        rail = 0
        direction = 1
        for ch in plaintext:
            rails[rail] += ch
            rail += direction
            if rail == 0 or rail == self.rails - 1:
                direction *= -1
        return ''.join(rails)

    def decrypt(self, ciphertext):
        """Decrypt ciphertext using Rail Fence cipher."""
        n = len(ciphertext)
        # Create the fence pattern
        fence = [[None] * n for _ in range(self.rails)]
        rail = 0
        direction = 1
        for i in range(n):
            fence[rail][i] = '*'
            rail += direction
            if rail == 0 or rail == self.rails - 1:
                direction *= -1
        # Fill the fence with ciphertext
        index = 0
        for r in range(self.rails):
            for c in range(n):
                if fence[r][c] == '*':
                    fence[r][c] = ciphertext[index]
                    index += 1
        # Read the fence in zigzag order
        result = []
        rail = 0
        direction = 1
        for i in range(n):
            result.append(fence[rail][i])
            rail += direction
            if rail == 0 or rail == self.rails - 1:
                direction *= -1
        return ''.join(result)

    def frequency_analysis(self, text):
        """Frequency analysis of letters in the text."""
        text = text.upper()
        freq = Counter(ch for ch in text if ch in ALPHABET)
        total = sum(freq.values())
        return {ch: freq[ch]/total for ch in ALPHABET}


class SubstitutionCipher:
    """Substitution cipher implementation."""

    def __init__(self, key=None):
        """Initialize with a key string representing the substitution alphabet.
        Key should be a 26-character string with unique letters."""
        if key is None:
            # Default to identity mapping
            self.key = ALPHABET
        else:
            key = key.upper()
            if len(key) != 26 or len(set(key)) != 26:
                raise ValueError("Key must be 26 unique letters.")
            self.key = key

        self.encrypt_map = dict(zip(ALPHABET, self.key))
        self.decrypt_map = dict(zip(self.key, ALPHABET))

    def encrypt(self, plaintext):
        """Encrypt plaintext using substitution cipher."""
        result = []
        for ch in plaintext.upper():
            if ch in ALPHABET:
                result.append(self.encrypt_map[ch])
            else:
                result.append(ch)
        return ''.join(result)

    def decrypt(self, ciphertext):
        """Decrypt ciphertext using substitution cipher."""
        result = []
